    /**
     * Valid From
     */
    valid_from: string;
    /**
     * Valid Until
     */
    valid_until?: string | null;
    /**
     * Accepted At
     */
    accepted_at?: string | null;
    /**
     * Created At
     */
    created_at: string;
    /**
     * Has Account
     */
    has_account: boolean;
    /**
     * Invited At
     */
    invited_at?: string | null;
    invite_status: MembershipRecordInviteStatus;
    /**
     * Can Invite
     */
    can_invite: boolean;
    /**
     * Invite Blocked Reason
     */
